    perspective_projection: ?*const fn (?*ke_render_camera, ?*const ke_camera_component, f32, ?*math.ke_mat4) callconv(.c) void,
    /// The perspective frustum the camera's field of view describes, whatever its `orthographic`
    /// flag says.
    perspective_frustum: ?*const fn (?*ke_render_camera, ?*const ke_camera_component, f32, ?*ke_camera_frustum) callconv(.c) void,
};

/// Owning wrapper: `ref` borrows for the lifetime, `destroy` ends it.
pub const ke_render_camera_handle = extern struct {
    ref: ?*ke_render_camera,
    destroy: ?*const fn (?*ke_render_camera) callconv(.c) void,
