pub const ke_gpu_command_encoder = extern struct {
    handle: ?*anyopaque,
    begin_render_pass: ?*const fn (?*ke_gpu_command_encoder, ?*const ke_gpu_render_pass_params) callconv(.c) ?*ke_gpu_render_pass,
