    copy_buffer_to_texture: ?*const fn (?*ke_gpu_command_encoder, ke_gpu_buffer, usize, u32, ke_gpu_texture, u32, u32, u32, u32, u32) callconv(.c) result.ke_result,
    copy_texture_to_texture: ?*const fn (?*ke_gpu_command_encoder, ke_gpu_texture, ke_gpu_texture, u32, u32) callconv(.c) void,
