/// The surface a frame is drawn into. A frame is one acquire followed, once the frame's command
/// buffers were submitted, by one present.
pub const ke_gpu_render_target = extern struct {
    handle: ?*anyopaque,
    /// Begins a frame and writes the view to draw into, owned by the target and valid until present.
    /// Succeeds writing KE_GPU_INVALID_HANDLE when the target has nothing to draw into this frame,
    /// and fails writing it when acquiring failed.
    acquire: ?*const fn (?*ke_gpu_render_target, ?*ke_gpu_texture_view) callconv(.c) result.ke_result,
    /// Ends the frame begun by acquire. Fails with KE_RESULT_INVALID_ARGUMENT when no frame is
    /// acquired.
    present: ?*const fn (?*ke_gpu_render_target) callconv(.c) result.ke_result,
    /// Size in pixels of the view the last acquire returned, or of the next one before any acquire.
    size: ?*const fn (?*ke_gpu_render_target, ?*u32, ?*u32) callconv(.c) void,
    /// Texel format of every view acquire returns.
    format: ?*const fn (?*ke_gpu_render_target) callconv(.c) ke_gpu_texture_format,
};

pub const ke_gpu_render_target_handle = extern struct {
    ref: ?*ke_gpu_render_target,
    destroy: ?*const fn (?*ke_gpu_render_target) callconv(.c) void,
};

