    begin_render: ?*const fn (?*ke_render_pass_ctx) callconv(.c) ?*ke_gpu_render_pass,
    begin_compute: ?*const fn (?*ke_render_pass_ctx) callconv(.c) ?*ke_gpu_compute_pass,
    encoder: ?*const fn (?*ke_render_pass_ctx) callconv(.c) ?*ke_gpu_command_encoder,
    query_ext: ?*const fn (?*ke_render_pass_ctx, ?[*:0]const u8) callconv(.c) ?*const anyopaque,
    backbuffer_size: ?*const fn (?*ke_render_pass_ctx, ?*u32, ?*u32) callconv(.c) void,
    /// The view of the color a pass in the chain samples: the current color before its link.
    /// KE_GPU_INVALID_HANDLE for a pass drawing over it or outside the chain.
    color_source: ?*const fn (?*ke_render_pass_ctx) callconv(.c) ke_gpu_texture_view,
};

pub const ke_render_service = extern struct {
    handle: ?*anyopaque,
    /// Declares a transient resource the service allocates and recycles.
    declare: ?*const fn (?*ke_render_service, ?*const ke_render_resource_params, ?*ecs.ke_component_id) callconv(.c) result.ke_result,
    /// Imports an externally-owned texture under `name`.
    import_texture: ?*const fn (?*ke_render_service, ?[*:0]const u8, ke_gpu_texture, ?*ecs.ke_component_id) callconv(.c) result.ke_result,
    /// Mints a tag cid under `name` with no GPU payload.
    import_tag: ?*const fn (?*ke_render_service, ?[*:0]const u8, ?*ecs.ke_component_id) callconv(.c) result.ke_result,
    /// Publishes an externally-owned GPU buffer under `name` for another pass to bind by name.
    import_buffer: ?*const fn (?*ke_render_service, ?[*:0]const u8, ke_gpu_buffer, u64, ?*ecs.ke_component_id) callconv(.c) result.ke_result,
    cid: ?*const fn (?*ke_render_service, ?[*:0]const u8) callconv(.c) ecs.ke_component_id,
    /// Opens a pass's recording context, from inside a render system's body.
    begin_pass: ?*const fn (?*ke_render_service, ?*const ke_render_pass_io) callconv(.c) ?*ke_render_pass_ctx,
    /// Closes a recording context opened by begin_pass.
    end_pass: ?*const fn (?*ke_render_service, ?*ke_render_pass_ctx) callconv(.c) void,
    /// Acquires the service's render target as the backbuffer (a built-in resource named
    /// "backbuffer"), clears the per-pass command slot table, and clears the frame's color and
    /// depth. When the target has nothing to draw into this frame it succeeds without beginning one,
    /// and begin_pass then opens no pass; it fails with the target's code when acquiring failed.
    begin_frame: ?*const fn (?*ke_render_service) callconv(.c) result.ke_result,
    /// Submits the passes outside the chain in the order they ended, then the chain in its order,
    /// then draws the frame's color into the backbuffer and presents the render target. A link whose
    /// pass recorded nothing still carries the color through it. Succeeds doing nothing when no
    /// frame began, and fails with the target's code when presenting failed.
    end_frame: ?*const fn (?*ke_render_service) callconv(.c) result.ke_result,
    /// Uploads interleaved vertices and 16-bit indices to device buffers.
    upload_mesh: ?*const fn (?*ke_render_service, ?[*:0]const u8, ?*const anyopaque, usize, ?*const u16, u32, ?*ke_mesh_handle) callconv(.c) result.ke_result,
    /// Resolves a mesh handle to its GPU buffers. Returns false for a handle this service never
    /// uploaded.
    mesh_buffers: ?*const fn (?*ke_render_service, ke_mesh_handle, ?*ke_gpu_buffer, ?*ke_gpu_buffer, ?*u32) callconv(.c) bool,
    /// The color a pass clears its color attachments to (begin_render LOAD_OP_CLEAR).
    set_clear_color: ?*const fn (?*ke_render_service, f32, f32, f32, f32) callconv(.c) void,
    upload_texture: ?*const fn (?*ke_render_service, ?[*:0]const u8, u32, u32, ?*const anyopaque, ?*ke_texture_handle) callconv(.c) result.ke_result,
    create_material: ?*const fn (?*ke_render_service, ?[*:0]const u8, ?*const f32, f32, f32, ke_texture_handle, ke_texture_handle, ke_alpha_mode, f32, f32, f32, ?[*:0]const u8, ?*ke_material_handle) callconv(.c) result.ke_result,
    /// What the service's resource binder holds for a material handle, the argument a pass gives its
    /// bind_material; an unknown handle resolves to the built-in white material.
    material_binding: ?*const fn (?*ke_render_service, ke_material_handle) callconv(.c) ke_render_material_binding,
    /// The pass bucket for a material handle, resolved from CPU-side storage — no GPU state touched.
    material_alpha_mode: ?*const fn (?*ke_render_service, ke_material_handle) callconv(.c) ke_alpha_mode,
    /// The MASK discard threshold for a material handle.
    material_alpha_cutoff: ?*const fn (?*ke_render_service, ke_material_handle) callconv(.c) f32,
    upload_cubemap: ?*const fn (?*ke_render_service, ?[*:0]const u8, u32, ?*const anyopaque, ?*ke_texture_handle) callconv(.c) result.ke_result,
    /// The GPU view for a texture/cubemap handle.
    texture_view: ?*const fn (?*ke_render_service, ke_texture_handle) callconv(.c) ke_gpu_texture_view,
    /// The GPU view of a declared transient resource, by name.
    resource_view: ?*const fn (?*ke_render_service, ?[*:0]const u8) callconv(.c) ke_gpu_texture_view,
    /// The raw GPU texture behind a declared resource, for the copy operations that take a texture
    /// rather than a view.
    resource_texture: ?*const fn (?*ke_render_service, ?[*:0]const u8) callconv(.c) ke_gpu_texture,
    /// The GPU buffer published under `name` via import_buffer.
    resource_buffer: ?*const fn (?*ke_render_service, ?[*:0]const u8) callconv(.c) ke_gpu_buffer,
    /// The size (bytes) of the buffer published under `name`.
    resource_buffer_size: ?*const fn (?*ke_render_service, ?[*:0]const u8) callconv(.c) u64,
    /// The backbuffer's pixel size, callable from any phase. Refreshed once per frame at
    /// begin_frame, so a caller earlier in the tick reads the previous frame's size.
    backbuffer_size: ?*const fn (?*ke_render_service, ?*u32, ?*u32) callconv(.c) void,
    /// Records a buffer upload to be flushed single-threaded at end_frame (before submit).
    upload: ?*const fn (?*ke_render_service, ke_gpu_buffer, u64, ?*const anyopaque, usize) callconv(.c) void,
    /// Returns the pipeline for this exact params state, compiling it on first request.
    get_or_create_pipeline: ?*const fn (?*ke_render_service, ?*const ke_gpu_render_pipeline_params) callconv(.c) ke_gpu_pipeline,
    /// The authored-material shader name a material handle was created with (see create_material's
    /// `shader`).
    material_shader: ?*const fn (?*ke_render_service, ke_material_handle) callconv(.c) ?[*:0]const u8,
    /// Adds a reference to a mesh, keeping it resident.
    retain_mesh: ?*const fn (?*ke_render_service, ke_mesh_handle) callconv(.c) void,
    /// Drops a reference to a mesh, freeing it at zero.
    release_mesh: ?*const fn (?*ke_render_service, ke_mesh_handle) callconv(.c) void,
    /// Adds a reference to a texture, keeping it resident.
    retain_texture: ?*const fn (?*ke_render_service, ke_texture_handle) callconv(.c) void,
    /// Drops a reference to a texture, freeing it at zero.
    release_texture: ?*const fn (?*ke_render_service, ke_texture_handle) callconv(.c) void,
    /// Adds a reference to a material, keeping it resident.
    retain_material: ?*const fn (?*ke_render_service, ke_material_handle) callconv(.c) void,
    /// Drops a reference to a material, freeing it at zero.
    release_material: ?*const fn (?*ke_render_service, ke_material_handle) callconv(.c) void,
    /// Path-keyed probe for a resident mesh upload: on a hit, retains and writes the resident handle
    /// to `out`. try_get_texture also serves cubemaps (shared cache).
    try_get_mesh: ?*const fn (?*ke_render_service, ?[*:0]const u8, ?*ke_mesh_handle) callconv(.c) bool,
    /// Path-keyed probe for a resident texture upload.
    try_get_texture: ?*const fn (?*ke_render_service, ?[*:0]const u8, ?*ke_texture_handle) callconv(.c) bool,
    /// Path-keyed probe for a resident material.
    try_get_material: ?*const fn (?*ke_render_service, ?[*:0]const u8, ?*ke_material_handle) callconv(.c) bool,
    /// The built-in 1×1 white texture, resolvable everywhere a neutral albedo is wanted.
    white_texture: ?*const fn (?*ke_render_service) callconv(.c) ke_texture_handle,
    /// Resolves a shader by logical NAME + STAGE to a device-ready module.
    load_shader: ?*const fn (?*ke_render_service, ?[*:0]const u8, ke_gpu_shader_stage, ?*ke_gpu_shader_module) callconv(.c) result.ke_result,
    /// Replaces the frame globals and records their upload; a shader reads them as `ke_frame`.
    set_frame_globals: ?*const fn (?*ke_render_service, ?*const ke_render_frame_globals) callconv(.c) void,
    /// The frame globals last set, zero before the first.
    frame_globals: ?*const fn (?*ke_render_service) callconv(.c) ?*const ke_render_frame_globals,
    /// Replaces the scene's light and records its upload; a shader reads it as `ke_lighting`.
    set_lighting: ?*const fn (?*ke_render_service, ?*const ke_render_lighting) callconv(.c) void,
    /// The scene's light last set, zero before the first.
    lighting: ?*const fn (?*ke_render_service) callconv(.c) ?*const ke_render_lighting,
    /// The resource binder the service was created with, through which a pass brings its resources
    /// to its shaders; the service has given it `ke_frame`, `ke_lighting` and the `ke_samp_*`
    /// samplers.
    resource_binder: ?*const fn (?*ke_render_service) callconv(.c) ?*ke_render_resource_binder,
    /// Texel format of the backbuffer, the format a pipeline drawing into it declares.
    backbuffer_format: ?*const fn (?*ke_render_service) callconv(.c) ke_gpu_texture_format,
    /// Texel format of the named texture resource, the format a pipeline drawing into it declares;
    /// KE_GPU_TEXTURE_FORMAT_INVALID for an unknown name or a resource without one.
    resource_format: ?*const fn (?*ke_render_service, ?[*:0]const u8) callconv(.c) ke_gpu_texture_format,
    /// Counts the times the targets declared relative to the backbuffer were recreated, which
    /// `begin_frame` does when the backbuffer changes size. A pass that keeps something made from a
    /// declared target's view, a bind group for instance, rebuilds it when the count changes.
    resource_generation: ?*const fn (?*ke_render_service) callconv(.c) u32,
    /// Gives a pass a place in the chain, after every pass that joined the same stage before it. The
    /// place is kept until leave_chain.
    join_chain: ?*const fn (?*ke_render_service, ke_render_stage, ke_render_chain_mode, ?*ke_render_chain_link) callconv(.c) result.ke_result,
    /// Gives the place back. An unknown link is ignored.
    leave_chain: ?*const fn (?*ke_render_service, ke_render_chain_link) callconv(.c) void,
    /// Texel format of the color a pass of stage draws into, the format its pipeline declares.
    chain_format: ?*const fn (?*ke_render_service, ke_render_stage) callconv(.c) ke_gpu_texture_format,
};

pub const ke_render_service_handle = extern struct {
    ref: ?*ke_render_service,
    destroy: ?*const fn (?*ke_render_service) callconv(.c) void,
};
